20: // NewIndex opens or creates a new Index backed by SQLite at dbPath.
21: // It configures WAL mode for better concurrency.
22: func NewIndex(dbPath string) (*Index, error) {
23: 	dsn := fmt.Sprintf("file:%s?_pragma=journal_mode(WAL)&_pragma=busy_timeout(5000)", dbPath)
24: 	db, err := sql.Open("sqlite", dsn)
25: 	if err != nil {
26: 		return nil, fmt.Errorf("opening index database: %w", err)
27: 	}
28: 
29: 	idx := &Index{db: db}
30: 	if err := idx.initSchema(); err != nil {
31: 		db.Close()
32: 		return nil, err
33: 	}
34: 	return idx, nil
35: }
36: 
37: // NewReadOnlyIndex opens an Index backed by SQLite at dbPath in read-only mode.
38: func NewReadOnlyIndex(dbPath string) (*Index, error) {
39: 	dsn := fmt.Sprintf("file:%s?mode=ro", dbPath)
40: 	db, err := sql.Open("sqlite", dsn)
41: 	if err != nil {
42: 		return nil, fmt.Errorf("opening read-only index database: %w", err)
43: 	}
44: 	return &Index{db: db}, nil
45: }
