151: // SearchEpisodes performs a full-text search against the episodes FTS table.
152: func (idx *Index) SearchEpisodes(ctx context.Context, matchQuery string) ([]EpisodeRecord, error) {
153: 	query := `
154: 	SELECT episode_id, session_id, content, snippet(episodes_fts, 2, '>', '', '...', 64), files_touched, outcomes, date 
155: 	FROM episodes_fts 
156: 	WHERE episodes_fts MATCH ?
157: 	ORDER BY bm25(episodes_fts)
158: 	`
159: 	rows, err := idx.db.QueryContext(ctx, query, matchQuery)
160: 	if err != nil {
161: 		return nil, fmt.Errorf("searching episodes: %w", err)
162: 	}
163: 	defer rows.Close()
164: 
165: 	var results []EpisodeRecord
166: 	for rows.Next() {
