168: 		var dateStr string
169: 		if err := rows.Scan(&r.EpisodeID, &r.SessionID, &r.Content, &r.Snippet, &r.FilesTouched, &r.Outcomes, &dateStr); err != nil {
170: 			return nil, fmt.Errorf("scanning search result: %w", err)
171: 		}
172: 		if d, err := time.Parse(time.RFC3339, dateStr); err == nil {
173: 			r.Date = d
174: 		}
175: 		results = append(results, r)
176: 	}
177: 	return results, rows.Err()
