418: // Resolve follows the alias chain to the current scope name.
419: // Prevents infinite loops (max depth 10 and cycle detection).
420: func (a *AliasMap) Resolve(scope string) string {
421: 	if a == nil || a.aliases == nil {
422: 		return scope
423: 	}
424: 	current := strings.TrimSpace(scope)
425: 	if current == "" {
426: 		return ""
427: 	}
428: 
429: 	maxDepth := 10
430: 	visited := make(map[string]bool)
431: 
432: 	for depth := 0; depth < maxDepth; depth++ {
433: 		next, exists := a.aliases[current]
434: 		if !exists || next == "" || next == current {
435: 			break
436: 		}
437: 		if visited[next] {
438: 			break
439: 		}
440: 		visited[current] = true
441: 		current = next
442: 	}
443: 	return current
444: }
