func TestBackwardCompatibility_EntitiesAndClaims(t *testing.T) {
	idx, cleanup := setupTestIndex(t)
	defer cleanup()

	ctx := context.Background()

	// 1. Entities Registry
	ent := entities.Entity{
		ID:   "pkg:foo",
		Kind: entities.KindFile,
		Name: "foo.go",
	}
	if err := idx.PutEntity(ctx, ent); err != nil {
		t.Fatalf("PutEntity: %v", err)
	}
